export type Subject = "Physics" | "Chemistry" | "Botany" | "Zoology";

export type Test = {
  id: string; // slug = ParikshaGruh Test Id; used for data/<id>.* + display
  sourceFile: string; // questions.source_file + upload_jobs.filename (dedup/rollback key) — STABLE per test
  pdf: string; // absolute path to the ONE canonical file we render (prefer the answer copy)
  questionCount: number;
  hasKey: boolean; // official `Answer : X` present in the text layer → keys extracted, else derived+flagged
  subjects: Subject[]; // subjects present; 1 for a topic test, 4 for a full mock
  chapterHint?: string; // whole-test NCERT chapter when the title names a topic (one of NEET_CHAPTERS[subject])
  note: string; // pyqNote-style provenance: source title (+ Test Id)
};

