export function requireTest(id: string | undefined): Test {
  if (!id || !TESTS[id]) throw new Error(`unknown test "${id}". Known: ${Object.keys(TESTS).join(", ")}`);
  return TESTS[id];
}

export const dataPath = (id: string, shard: string) => join(DATA, `${id}.${shard.toLowerCase()}.json`);

